type TreeNode = { val: number; left: TreeNode | null; right: TreeNode | null };
function branchNotebookFirstQualifyingSlip(root: TreeNode | null, k: number): number {
  const a=root; let out:number[]=[];
  function visit(node:TreeNode|null):void{if(!node)return;out.push(node.val);visit(node.left);visit(node.right);}visit(a);
  return out.find(x=>x>=k)??-1;
}


python
def branchNotebookFirstQualifyingSlip(root, k):
    a=root
    out=[]
    def visit(node):
        if not node: return
        out.append(node.val)
        visit(node.left)
        visit(node.right)
    visit(a)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int branchNotebookFirstQualifyingSlip(TreeNode root, int k) {
    TreeNode a=root; List<Integer> out=new ArrayList<>();
    {class Walk {void visit(TreeNode node){if(node==null)return;out.add(node.val);visit(node.left);visit(node.right);}}new Walk().visit(a);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
